#!/usr/bin/env python3
"""
benchmark.py

Multi-API benchmark harness with streaming TTFT measurement.

Requirements:
- stdlib only
- urllib.request for HTTP
- manual SSE parsing
- ThreadPoolExecutor for parallelism
- Python 3.9+
"""

from __future__ import annotations

import argparse
import concurrent.futures
import datetime as dt
import json
import os
import socket
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
import uuid
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


FIXED_PROMPT = "Reply with exactly one sentence about the color blue."


def iso_utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat().replace("+00:00", "Z")


def round_ms(value_seconds: float) -> float:
    return round(value_seconds * 1000.0, 3)


def clip_text(text: str, limit: int = 500) -> str:
    text = text.replace("\r", " ").replace("\n", " ").strip()
    if len(text) > limit:
        return text[:limit] + "..."
    return text


def load_json_file(path: str) -> Dict[str, Any]:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def join_url(base_url: str, endpoint: str) -> str:
    return base_url.rstrip("/") + endpoint


def get_api_key(api_key_env: Optional[str]) -> Optional[str]:
    if not api_key_env:
        return None
    value = os.getenv(api_key_env)
    if not value:
        raise ValueError(f"API key environment variable '{api_key_env}' is not set")
    return value.strip()


def build_request_payload(model_cfg: Dict[str, Any], prompt: str) -> Tuple[str, Dict[str, Any]]:
    model_id = model_cfg.get("id")
    api_type = model_cfg.get("api_type")
    base_url = model_cfg.get("base_url")

    if not model_id:
        raise ValueError("Missing model id")
    if api_type not in ("chat_completions", "responses"):
        raise ValueError(f"Unsupported api_type '{api_type}'")
    if not base_url:
        raise ValueError(f"Model '{model_id}': missing base_url")

    payload: Dict[str, Any] = {
        "model": model_id,
        "stream": True,
    }

    if "temperature" in model_cfg and model_cfg["temperature"] is not None:
        payload["temperature"] = model_cfg["temperature"]

    if api_type == "chat_completions":
        payload["messages"] = [{"role": "user", "content": prompt}]
        if "max_tokens" in model_cfg and model_cfg["max_tokens"] is not None:
            payload["max_tokens"] = model_cfg["max_tokens"]
        endpoint = "/v1/chat/completions"
    else:
        payload["input"] = prompt
        # Responses API typically uses max_output_tokens.
        if "max_tokens" in model_cfg and model_cfg["max_tokens"] is not None:
            payload["max_output_tokens"] = model_cfg["max_tokens"]
        endpoint = "/v1/responses"

    return join_url(base_url, endpoint), payload


def make_headers(api_key: Optional[str]) -> Dict[str, str]:
    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "Cache-Control": "no-cache",
    }
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    return headers


def extract_content_delta(api_type: str, event_obj: Dict[str, Any]) -> Optional[str]:
    """
    Extract the textual delta from a parsed JSON SSE event.
    """
    if api_type == "chat_completions":
        choices = event_obj.get("choices")
        if not isinstance(choices, list) or not choices:
            return None
        first = choices[0]
        if not isinstance(first, dict):
            return None
        delta = first.get("delta")
        if not isinstance(delta, dict):
            return None
        content = delta.get("content")
        if isinstance(content, str) and content != "":
            return content
        return None

    if api_type == "responses":
        event_type = event_obj.get("type")
        # Required by task:
        # data: {"type": "content_block_delta", "delta": {"text": "..."}}
        if event_type == "content_block_delta":
            delta = event_obj.get("delta")
            if isinstance(delta, dict):
                text = delta.get("text")
                if isinstance(text, str) and text != "":
                    return text
        # Optional robustness for other OpenAI-like response stream variants.
        if event_type in ("response.output_text.delta", "output_text.delta"):
            delta = event_obj.get("delta")
            if isinstance(delta, str) and delta != "":
                return delta
            if isinstance(delta, dict):
                text = delta.get("text")
                if isinstance(text, str) and text != "":
                    return text
        return None

    return None


def format_http_error(e: urllib.error.HTTPError) -> str:
    body_text = ""
    try:
        raw = e.read()
        if raw:
            body_text = raw.decode("utf-8", errors="replace").strip()
    except Exception:
        body_text = ""
    if body_text:
        return f"HTTP {e.code} {e.reason}: {clip_text(body_text)}"
    return f"HTTP {e.code} {e.reason}"


def format_exception(e: BaseException) -> str:
    if isinstance(e, urllib.error.HTTPError):
        return format_http_error(e)
    if isinstance(e, urllib.error.URLError):
        return f"Connection error: {clip_text(str(e.reason))}"
    if isinstance(e, socket.timeout):
        return "Connection timeout"
    if isinstance(e, json.JSONDecodeError):
        return f"JSON parse error: {clip_text(str(e))}"
    return clip_text(str(e) or e.__class__.__name__)


def process_stream(
    response: Any,
    api_type: str,
    model_id: str,
    t_start: float,
) -> Dict[str, Any]:
    content_parts: List[str] = []
    first_token: Optional[str] = None
    t_first_token: Optional[float] = None

    # SSE event assembly
    data_lines: List[str] = []

    def flush_event() -> None:
        nonlocal data_lines, first_token, t_first_token
        if not data_lines:
            return

        payload = "\n".join(data_lines).strip()
        data_lines = []

        if not payload or payload == "[DONE]":
            return

        event_obj = json.loads(payload)
        delta = extract_content_delta(api_type, event_obj)
        if delta is None or delta == "":
            return

        content_parts.append(delta)
        if first_token is None and delta.strip() != "":
            first_token = delta.strip()
            t_first_token = time.perf_counter()

    while True:
        raw_line = response.readline()
        if raw_line == b"":
            break

        line = raw_line.decode("utf-8", errors="replace").rstrip("\r\n")

        if line == "":
            flush_event()
            continue

        if line.startswith("data:"):
            data = line[5:]
            if data.startswith(" "):
                data = data[1:]
            data_lines.append(data)
        # Ignore other SSE fields like event:, id:, retry:, comments, etc.

    # Flush any pending event if stream ends without a blank line.
    flush_event()

    t_end = time.perf_counter()
    total_ms = round_ms(t_end - t_start)

    if first_token is None:
        return {
            "model_id": model_id,
            "api_type": api_type,
            "status": "error",
            "ttft_ms": None,
            "total_ms": total_ms,
            "first_token": None,
            "full_response": None,
            "error": "No non-empty content delta received",
        }

    return {
        "model_id": model_id,
        "api_type": api_type,
        "status": "ok",
        "ttft_ms": round_ms(t_first_token - t_start) if t_first_token is not None else None,
        "total_ms": total_ms,
        "first_token": first_token,
        "full_response": "".join(content_parts),
        "error": None,
    }


def benchmark_one_model(model_cfg: Dict[str, Any], prompt: str, timeout: float) -> Dict[str, Any]:
    model_id = str(model_cfg.get("id", ""))
    api_type = model_cfg.get("api_type")

    # Default error result scaffold.
    def error_result(total_ms: float, message: str) -> Dict[str, Any]:
        return {
            "model_id": model_id,
            "api_type": api_type,
            "status": "error",
            "ttft_ms": None,
            "total_ms": round(total_ms, 3),
            "first_token": None,
            "full_response": None,
            "error": message,
        }

    t0 = time.perf_counter()
    t_start = t0

    try:
        url, payload = build_request_payload(model_cfg, prompt)
        api_key = get_api_key(model_cfg.get("api_key_env"))
        headers = make_headers(api_key)
        body = json.dumps(payload).encode("utf-8")

        req = urllib.request.Request(url, data=body, headers=headers, method="POST")
        t_start = time.perf_counter()

        with urllib.request.urlopen(req, timeout=timeout) as response:
            return process_stream(response, api_type, model_id, t_start)

    except Exception as e:
        total_ms = round_ms(time.perf_counter() - t_start)
        return error_result(total_ms, format_exception(e))


def summarize_results(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    ok_results = [
        r for r in results
        if r.get("status") == "ok" and isinstance(r.get("ttft_ms"), (int, float))
    ]
    ok_count = len(ok_results)
    error_count = len(results) - ok_count

    avg_ttft_ms: Optional[float]
    fastest_model: Optional[str]
    slowest_model: Optional[str]

    if ok_results:
        ttfts = [float(r["ttft_ms"]) for r in ok_results]
        avg_ttft_ms = round(sum(ttfts) / len(ttfts), 3)

        fastest = min(ok_results, key=lambda r: float(r["ttft_ms"]))
        slowest = max(ok_results, key=lambda r: float(r["ttft_ms"]))
        fastest_model = fastest["model_id"]
        slowest_model = slowest["model_id"]
    else:
        avg_ttft_ms = None
        fastest_model = None
        slowest_model = None

    return {
        "total": len(results),
        "ok": ok_count,
        "errors": error_count,
        "avg_ttft_ms": avg_ttft_ms,
        "fastest_model": fastest_model,
        "slowest_model": slowest_model,
    }


def run_benchmark(
    config_path: str,
    output_path: str,
    timeout: float,
    workers: int,
) -> Dict[str, Any]:
    config = load_json_file(config_path)
    models = config.get("models")
    if not isinstance(models, list):
        raise ValueError("Config file must contain a top-level 'models' array")

    results: List[Optional[Dict[str, Any]]] = [None] * len(models)

    def task(index: int, model_cfg: Dict[str, Any]) -> Tuple[int, Dict[str, Any]]:
        result = benchmark_one_model(model_cfg, FIXED_PROMPT, timeout)
        return index, result

    if workers < 1:
        raise ValueError("--workers must be >= 1")

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
        futures = [executor.submit(task, i, m) for i, m in enumerate(models)]
        for future in concurrent.futures.as_completed(futures):
            index, result = future.result()
            results[index] = result

    final_results: List[Dict[str, Any]] = [r for r in results if r is not None]

    output_obj = {
        "run_id": str(uuid.uuid4()),
        "timestamp": iso_utc_now(),
        "prompt": FIXED_PROMPT,
        "results": final_results,
        "summary": summarize_results(final_results),
    }

    out_path = Path(output_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(output_obj, f, indent=2, ensure_ascii=False)

    return output_obj


def parse_args(argv: List[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Multi-API streaming TTFT benchmark harness")
    parser.add_argument("--config", required=True, help="Path to model config JSON")
    parser.add_argument(
        "--output",
        default="benchmark_results.json",
        help="Output file path (default: benchmark_results.json)",
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=30.0,
        help="Per-model timeout in seconds (default: 30)",
    )
    parser.add_argument(
        "--workers",
        type=int,
        default=1,
        help="Parallel workers (default: 1)",
    )
    return parser.parse_args(argv)


def main(argv: Optional[List[str]] = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)

    try:
        run_benchmark(
            config_path=args.config,
            output_path=args.output,
            timeout=float(args.timeout),
            workers=int(args.workers),
        )
    except Exception as e:
        print(f"benchmark.py: {format_exception(e)}", file=sys.stderr)
        return 1

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
